<?php
declare(strict_types=1);
$root=dirname(__DIR__,2);
$checks=0;$failures=[];
$assert=static function(bool $ok,string $label) use (&$checks,&$failures):void{$checks++;if(!$ok)$failures[]=$label;};
$read=static function(string $path) use($root):string{$v=file_get_contents($root.'/'.$path);if(!is_string($v))throw new RuntimeException('Unable to read '.$path);return $v;};
$aicsConfig=$read('aics/config.php');$maifipConfig=$read('maifip/config.php');
$assert(str_contains($aicsConfig,"const APP_VERSION = '0.0220'") && str_contains($aicsConfig,"const FAMS_VERSION = '0.0220'"),'AICS version markers');
$assert(str_contains($read('maifip/app_version.php'),"const APP_VERSION = '0.0220'"),'MAIFIP version marker');
$assert(str_contains($aicsConfig,'CREATE TABLE IF NOT EXISTS fams_deleted_records') && !preg_match('/try\s*\{\s*\$pdo->exec\("CREATE TABLE IF NOT EXISTS fams_deleted_records/s',$aicsConfig),'AICS archive table creation fails visibly');
$assert(str_contains($maifipConfig,'CREATE TABLE IF NOT EXISTS fams_deleted_records') && !preg_match('/try\s*\{\s*\$pdo->exec\("CREATE TABLE IF NOT EXISTS fams_deleted_records/s',$maifipConfig),'MAIFIP archive table creation fails visibly');
$audit=$read('maifip/helpers.php');$auditFn=substr($audit,strpos($audit,'function ensure_action_logs_schema'),strpos($audit,'function fams_client_ip')-strpos($audit,'function ensure_action_logs_schema'));
$assert(str_contains($auditFn,'$pdo->inTransaction()'),'MAIFIP audit schema refuses DDL during transaction');
$assert(!str_contains($auditFn,'catch(Throwable'),'MAIFIP audit schema migration errors are not swallowed');
$assert(str_contains($auditFn,'$done=true;') && str_contains($auditFn,"'client_hostname'") && str_contains($auditFn,"'user_agent'"),'MAIFIP audit schema completion follows verified columns');
$maifipHelpers=$read('maifip/helpers.php');
$facilitySchema=substr($maifipHelpers,strpos($maifipHelpers,'function ensure_facility_schema'),strpos($maifipHelpers,'function facility_options')-strpos($maifipHelpers,'function ensure_facility_schema'));
$facilityData=substr($maifipHelpers,strpos($maifipHelpers,'function ensure_facility_data_schema'),strpos($maifipHelpers,'function ensure_control_number_schema')-strpos($maifipHelpers,'function ensure_facility_data_schema'));
$assert(!str_contains($facilitySchema,'catch(') && str_contains($facilitySchema,'$done=true;'),'MAIFIP facility schema migration is retryable and errors surface');
$assert(!str_contains($facilityData,'catch(') && strpos($facilityData,'DROP INDEX')>strpos($facilityData,'ADD UNIQUE KEY'),'MAIFIP facility uniqueness replacement is added before legacy key removal');
$assert(str_contains($maifipHelpers,'Offline synchronization schema could not be verified') && str_contains($maifipHelpers,'MAIFIP monthly-report facility uniqueness could not be verified'),'MAIFIP critical migration failures are surfaced');
$aicsHelpers=$read('aics/helpers.php');$recordFn=substr($aicsHelpers,strpos($aicsHelpers,'function ensure_record_schema'),strpos($aicsHelpers,'function expire_waiting_records')-strpos($aicsHelpers,'function ensure_record_schema'));
$assert(str_contains($recordFn,'$pdo->inTransaction()'),'AICS record schema refuses DDL during transaction');
$assert(!str_contains($recordFn,'catch(') && strpos($recordFn,'$done=true;')>strpos($recordFn,'UPDATE aics_assistance_records'),'AICS record migration completion occurs after successful updates');
$assert(str_contains($aicsHelpers,'$pdo->inTransaction()') && str_contains($aicsHelpers,'AICS avatar schema'),'AICS avatar DDL guarded outside transactions');
$ticket=$read('aics/tickets.php');$deleteTicket=$read('aics/delete_ticket_request.php');
$assert(str_contains($ticket,'INFORMATION_SCHEMA.COLUMNS') && !str_contains(substr($ticket,0,2500),'catch(Throwable $e){}'),'AICS ticket compatibility DDL is checked and visible');
$assert(str_contains($deleteTicket,'INFORMATION_SCHEMA.COLUMNS') && !str_contains($deleteTicket,'catch(Throwable $e){}'),'AICS delete-ticket endpoint uses checked compatibility DDL');
$assert(str_contains($read('maifip/delete_record.php'),'fams_shared_transaction') && str_contains($read('aics/records.php'),'fams_shared_transaction'),'Both direct archive/delete flows are transactional');
$assert(str_contains($read('maifip/ticket_review.php'),'fams_shared_transaction') && str_contains($read('aics/tickets.php'),'fams_shared_transaction'),'Both ticket decision workflows are transactional');
$assert(str_contains($read('maifip/tickets.php'),"throw new RuntimeException('Ticket history schema could not be verified.") && str_contains($read('maifip/ticket_review.php'),"throw new RuntimeException('Ticket history schema could not be verified."),'MAIFIP ticket DDL failures stop ticket actions rather than silently continuing');
$assert(str_contains($read('aics/users.php'),'Removed local AICS account ID ') && str_contains($read('maifip/users.php'),'Removed MAIFIP account ID {$uid}'),'Account removal audit preserves target account identifiers and names');
$assert(str_contains($read('maifip/trash.php'),'restored_at IS NULL') && str_contains($read('aics/trash.php'),'restored_at IS NULL'),'Restoration is guarded against replay');
$assert(str_contains($read('maifip/ticket_review.php'),'record_id=NULL') && str_contains($read('maifip/tickets.php'),'record_control_number'),'MAIFIP ticket history detaches record while retaining reference snapshot');
$archiveHelper=$read('core/audit_runtime.php');
$assert(str_contains($archiveHelper,'fams_archive_record_with_history') && str_contains($archiveHelper,'history_payload') && str_contains($archiveHelper,'aics_status_history') && str_contains($archiveHelper,'status_history'),'Shared archive stores the full workspace-specific status-history snapshot');
$assert(str_contains($archiveHelper,'UPDATE aics_tickets SET record_control_number=COALESCE(record_control_number,?),record_id=NULL') && str_contains($archiveHelper,'UPDATE revision_tickets SET record_control_number=COALESCE(record_control_number,?),record_facility=COALESCE(record_facility,?),record_id=NULL'),'Both workspaces detach ticket links while retaining control-number and facility snapshots');
$assert(str_contains($read('aics/config.php'),'history_payload LONGTEXT NULL') && str_contains($read('maifip/config.php'),'history_payload LONGTEXT NULL'),'Archive history snapshot column is migrated in both workspace bootstraps');
$aicsTickets=$read('aics/tickets.php');
$assert(str_contains($aicsTickets,'fams_deleted_records') && str_contains($aicsTickets,'APPROVE_DELETE_TICKET'),'AICS approved delete archives record and audits decision');
$assert(str_contains($aicsTickets,'record_control_number=?,record_id=NULL') && str_contains($aicsTickets,'UPDATE aics_tickets t JOIN fams_deleted_records'),'AICS ticket history snapshots control number and detaches deleted record references');
echo "Data lifecycle audit: {$checks} checks, ".count($failures)." failures\n";
foreach($failures as $failure)echo "FAIL: {$failure}\n";
exit($failures?1:0);
